mapper.select:
SELECT DISTINCT t.* FROM tasks t
LEFT JOIN task_assignees ta ON t.id = ta.task_id
WHERE t.is_deleted = false
  AND (

      (t.task_type = 'EVENT' AND (
          t.creator_id = #{userId}
          OR ta.user_id = #{userId}

          OR (t.visibility = 'PUBLIC'
              AND t.creator_id IN (
                  SELECT id FROM users WHERE department_id IN

                      #{id}

              )
          )

      ))
      OR

      (t.task_type = 'WBS_TASK' AND (
          ta.user_id = #{userId}

          OR t.creator_id = #{userId}

      ))
      OR

      (t.task_type = 'TODO' AND t.creator_id = #{userId})
  )

  AND t.start_date <= #{to}


  AND t.end_date >= #{from}


  AND (t.title LIKE CONCAT('%', #{keyword}, '%')
    OR t.description LIKE CONCAT('%', #{keyword}, '%'))

ORDER BY t.start_date
LIMIT 500

SELECT * FROM tasks
WHERE creator_id = #{userId}
  AND task_type = 'TODO'
  AND is_deleted = false

    AND status = #{status}


    AND project_id = #{projectId}


    AND title LIKE CONCAT('%', #{keyword}, '%')


    AND (start_date IS NULL OR start_date <= #{to})


    AND (end_date IS NULL OR end_date >= #{from})

ORDER BY sort_order, created_at DESC
